var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"# parallel-manifest-validate.sh: sourceable bash port of"},
{"lineNum":"    3","line":"# scripts/dev_tools/parallel_manifest_contract.py. Validates a parallel-run"},
{"lineNum":"    4","line":"# manifest document against invariants M1 through M7 and exposes the two"},
{"lineNum":"    5","line":"# default-resolving accessors that every consumer uses instead of reading"},
{"lineNum":"    6","line":"# `mode` and `max_concurrency` directly."},
{"lineNum":"    7","line":"#"},
{"lineNum":"    8","line":"# Section order is load-bearing and mirrors the Python module exactly: the M1"},
{"lineNum":"    9","line":"# frontmatter checks short-circuit with a single error; then run identity"},
{"lineNum":"   10","line":"# (M2 parallel, M3 mode, M4 max_concurrency, M5 created_at) in schema field"},
{"lineNum":"   11","line":"# order; then the M7 prohibited-key scan, deep results in document order"},
{"lineNum":"   12","line":"# followed by the top-level results; then the M6 items collection."},
{"lineNum":"   13","line":"#"},
{"lineNum":"   14","line":"# Every error string begins with the literal prefix `Parallel manifest` and"},
{"lineNum":"   15","line":"# ends with a period. The Python module remains the repository authority."},
{"lineNum":"   16","line":"#"},
{"lineNum":"   17","line":"# Out-of-subset input. When the YAML scanner refuses a construct it does not"},
{"lineNum":"   18","line":"# model, this module returns exit status 2 with the refusal detail in"},
{"lineNum":"   19","line":"# PM_SUBSET_DETAIL and emits no validation errors. Refusing to answer is"},
{"lineNum":"   20","line":"# deliberate: a guessed parse could disagree with the Python authority"},
{"lineNum":"   21","line":"# silently, whereas an explicit refusal is visible to the caller."},
{"lineNum":"   22","line":"#"},
{"lineNum":"   23","line":"# shellcheck disable=SC2034"},
{"lineNum":"   24","line":"# SC2034 is disabled file-wide because PM_SUBSET_DETAIL is written here and"},
{"lineNum":"   25","line":"# read by the entry point validate-parallel-manifest.sh, which shellcheck"},
{"lineNum":"   26","line":"# analyses as a separate file and therefore cannot see the use."},
{"lineNum":"   27","line":""},
{"lineNum":"   28","line":"# Resolve this file\'s own directory so its dependencies source regardless of"},
{"lineNum":"   29","line":"# the caller\'s working directory."},
{"lineNum":"   30","line":"PM_LIB_DIR=$(cd -- \"$(dirname -- \"${BASH_SOURCE[0]}\")\" && pwd)","class":"lineCov","hits":"1","order":"666",},
{"lineNum":"   31","line":"# shellcheck source=.claude/lib/bash/parallel-items-validate.sh"},
{"lineNum":"   32","line":"# shellcheck disable=SC1091"},
{"lineNum":"   33","line":"source \"$PM_LIB_DIR/parallel-items-validate.sh\"","class":"lineCov","hits":"1","order":"667",},
{"lineNum":"   34","line":""},
{"lineNum":"   35","line":"# Literal context prefix for every error this module and its helpers emit."},
{"lineNum":"   36","line":"PM_CONTEXT=\"Parallel manifest\"","class":"lineCov","hits":"1","order":"675",},
{"lineNum":"   37","line":""},
{"lineNum":"   38","line":"# Documented default run mode when the manifest omits `mode` (invariant M3)."},
{"lineNum":"   39","line":"PM_DEFAULT_MODE=\"closed\"","class":"lineCov","hits":"1","order":"654",},
{"lineNum":"   40","line":""},
{"lineNum":"   41","line":"# Documented default fan-out when the manifest omits `max_concurrency` (M4)."},
{"lineNum":"   42","line":"PM_DEFAULT_MAX_CONCURRENCY=4","class":"lineCov","hits":"1","order":"695",},
{"lineNum":"   43","line":""},
{"lineNum":"   44","line":"# Inclusive bounds on a present `max_concurrency` (invariant M4, A7)."},
{"lineNum":"   45","line":"PM_MIN_CONCURRENCY=1","class":"lineCov","hits":"1","order":"685",},
{"lineNum":"   46","line":"PM_MAX_CONCURRENCY=8","class":"lineCov","hits":"1","order":"661",},
{"lineNum":"   47","line":""},
{"lineNum":"   48","line":"# Keys the manifest rejects at any nesting level (invariant M7)."},
{"lineNum":"   49","line":"PM_DEEP_PROHIBITED_KEYS=\"depends_on\"","class":"lineCov","hits":"1","order":"670",},
{"lineNum":"   50","line":""},
{"lineNum":"   51","line":"# Keys the manifest rejects at the document root only (invariant M7)."},
{"lineNum":"   52","line":"PM_TOP_LEVEL_PROHIBITED_KEYS=\"integration_branch\"","class":"lineCov","hits":"1","order":"674",},
{"lineNum":"   53","line":""},
{"lineNum":"   54","line":"# Detail recorded when the parser refuses an out-of-subset construct."},
{"lineNum":"   55","line":"PM_SUBSET_DETAIL=\"\"","class":"lineCov","hits":"1","order":"683",},
{"lineNum":"   56","line":""},
{"lineNum":"   57","line":"pm_parse_manifest() {"},
{"lineNum":"   58","line":"\t# Parse manifest text into the shared node table (invariant M1)."},
{"lineNum":"   59","line":"\t#"},
{"lineNum":"   60","line":"\t# Args: $1 = raw manifest document text."},
{"lineNum":"   61","line":"\t# Returns 0 when the frontmatter parsed into a mapping. Returns 1 after"},
{"lineNum":"   62","line":"\t# appending the single M1 error to PC_ERRORS for a missing, unterminated,"},
{"lineNum":"   63","line":"\t# unparseable, or non-mapping block. Returns 2 without appending anything"},
{"lineNum":"   64","line":"\t# when the document uses a construct outside the supported subset."},
{"lineNum":"   65","line":"\tlocal text=\"$1\"","class":"lineCov","hits":"1","order":"677",},
{"lineNum":"   66","line":"\tif ! yp_extract_frontmatter_body \"$text\" \"$PM_CONTEXT\"; then","class":"lineCov","hits":"1","order":"686",},
{"lineNum":"   67","line":"\t\tpc_error_add \"$YP_FENCE_ERROR\"","class":"lineCov","hits":"1","order":"688",},
{"lineNum":"   68","line":"\t\treturn 1","class":"lineCov","hits":"1","order":"672",},
{"lineNum":"   69","line":"\tfi"},
{"lineNum":"   70","line":"\tif yp_parse_body; then","class":"lineCov","hits":"1","order":"665",},
{"lineNum":"   71","line":"\t\treturn 0","class":"lineCov","hits":"1","order":"681",},
{"lineNum":"   72","line":"\tfi"},
{"lineNum":"   73","line":"\t# Routing table for the three parser failure modes: a sequence or empty"},
{"lineNum":"   74","line":"\t# root is M1\'s non-mapping case, a malformed line is M1\'s YAML-error case,"},
{"lineNum":"   75","line":"\t# and an unsupported construct makes the module refuse to answer."},
{"lineNum":"   76","line":"\tcase \"$YP_STATUS\" in","class":"lineCov","hits":"1","order":"662",},
{"lineNum":"   77","line":"\tnot_a_mapping)"},
{"lineNum":"   78","line":"\t\tpc_error_add \"$PM_CONTEXT frontmatter must be a mapping.\"","class":"lineCov","hits":"1","order":"669",},
{"lineNum":"   79","line":"\t\treturn 1","class":"lineCov","hits":"1","order":"659",},
{"lineNum":"   80","line":"\t\t;;"},
{"lineNum":"   81","line":"\tyaml_error)"},
{"lineNum":"   82","line":"\t\tpc_error_add \"$PM_CONTEXT frontmatter is not valid YAML: $YP_DETAIL.\"","class":"lineCov","hits":"1","order":"657",},
{"lineNum":"   83","line":"\t\treturn 1","class":"lineCov","hits":"1","order":"655",},
{"lineNum":"   84","line":"\t\t;;"},
{"lineNum":"   85","line":"\t*)"},
{"lineNum":"   86","line":"\t\tPM_SUBSET_DETAIL=\"$YP_DETAIL\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   87","line":"\t\treturn 2","class":"lineNoCov","hits":"0",},
{"lineNum":"   88","line":"\t\t;;"},
{"lineNum":"   89","line":"\tesac"},
{"lineNum":"   90","line":"}"},
{"lineNum":"   91","line":""},
{"lineNum":"   92","line":"pm_validate_identity() {"},
{"lineNum":"   93","line":"\t# Validate run identity fields against invariants M2 through M5."},
{"lineNum":"   94","line":"\t#"},
{"lineNum":"   95","line":"\t# The mode and max_concurrency checks are presence gated because both keys"},
{"lineNum":"   96","line":"\t# are optional: absence is the documented authoring shape that the"},
{"lineNum":"   97","line":"\t# accessors resolve, so it must contribute no error."},
{"lineNum":"   98","line":"\tlocal slug_type slug_value","class":"lineCov","hits":"1","order":"653",},
{"lineNum":"   99","line":"\tslug_type=$(yp_type_of \"parallel\")","class":"lineCov","hits":"1","order":"663",},
{"lineNum":"  100","line":"\tslug_value=$(yp_value_of \"parallel\")","class":"lineCov","hits":"1","order":"679",},
{"lineNum":"  101","line":"\tif ! pc_is_non_empty_string \"$slug_type\" \"$slug_value\"; then","class":"lineCov","hits":"1","order":"652",},
{"lineNum":"  102","line":"\t\tpc_error_add \"$PM_CONTEXT parallel must be a non-empty string.\"","class":"lineCov","hits":"1","order":"651",},
{"lineNum":"  103","line":"\tfi"},
{"lineNum":"  104","line":""},
{"lineNum":"  105","line":"\tif yp_has \"mode\"; then","class":"lineCov","hits":"1","order":"660",},
{"lineNum":"  106","line":"\t\tlocal mode_type mode_value","class":"lineCov","hits":"1","order":"690",},
{"lineNum":"  107","line":"\t\tmode_type=$(yp_type_of \"mode\")","class":"lineCov","hits":"1","order":"691",},
{"lineNum":"  108","line":"\t\tmode_value=$(yp_value_of \"mode\")","class":"lineCov","hits":"1","order":"671",},
{"lineNum":"  109","line":"\t\tif [[ $mode_type != str ]] || ! pc_enum_members_contains \"$PC_VALID_MODES\" \"$mode_value\"; then","class":"lineCov","hits":"1","order":"692",},
{"lineNum":"  110","line":"\t\t\tpc_error_add \"$(pc_enum_error \"$PM_CONTEXT\" \"mode\" \"$PC_VALID_MODES\" \"$(pi_repr_at \"mode\")\")\"","class":"lineCov","hits":"1","order":"694",},
{"lineNum":"  111","line":"\t\tfi"},
{"lineNum":"  112","line":"\tfi"},
{"lineNum":"  113","line":""},
{"lineNum":"  114","line":"\tif yp_has \"max_concurrency\"; then","class":"lineCov","hits":"1","order":"684",},
{"lineNum":"  115","line":"\t\tlocal cap_type cap_value","class":"lineCov","hits":"1","order":"697",},
{"lineNum":"  116","line":"\t\tcap_type=$(yp_type_of \"max_concurrency\")","class":"lineCov","hits":"1","order":"698",},
{"lineNum":"  117","line":"\t\tcap_value=$(yp_value_of \"max_concurrency\")","class":"lineCov","hits":"1","order":"699",},
{"lineNum":"  118","line":"\t\tif ! pc_in_bounded_range \"$cap_type\" \"$cap_value\" \"$PM_MIN_CONCURRENCY\" \"$PM_MAX_CONCURRENCY\"; then","class":"lineCov","hits":"1","order":"700",},
{"lineNum":"  119","line":"\t\t\tpc_error_add \"$PM_CONTEXT max_concurrency must be an integer from $PM_MIN_CONCURRENCY through $PM_MAX_CONCURRENCY; found: $(pi_repr_at \"max_concurrency\").\"","class":"lineCov","hits":"1","order":"701",},
{"lineNum":"  120","line":"\t\tfi"},
{"lineNum":"  121","line":"\tfi"},
{"lineNum":"  122","line":""},
{"lineNum":"  123","line":"\tlocal created_type created_value","class":"lineCov","hits":"1","order":"702",},
{"lineNum":"  124","line":"\tcreated_type=$(yp_type_of \"created_at\")","class":"lineCov","hits":"1","order":"678",},
{"lineNum":"  125","line":"\tcreated_value=$(yp_value_of \"created_at\")","class":"lineCov","hits":"1","order":"687",},
{"lineNum":"  126","line":"\tif ! pc_is_non_empty_string \"$created_type\" \"$created_value\"; then","class":"lineCov","hits":"1","order":"689",},
{"lineNum":"  127","line":"\t\tpc_error_add \"$PM_CONTEXT created_at must be a non-empty string.\"","class":"lineCov","hits":"1","order":"673",},
{"lineNum":"  128","line":"\tfi"},
{"lineNum":"  129","line":"}"},
{"lineNum":"  130","line":""},
{"lineNum":"  131","line":"pm_validate_text() {"},
{"lineNum":"  132","line":"\t# Validate a manifest document against invariants M1 to M7."},
{"lineNum":"  133","line":"\t#"},
{"lineNum":"  134","line":"\t# Args: $1 = raw manifest document text, authored with LF, CRLF, or CR"},
{"lineNum":"  135","line":"\t# line endings."},
{"lineNum":"  136","line":"\t# Returns 0 after populating PC_ERRORS with the complete error list, which"},
{"lineNum":"  137","line":"\t# is empty for a valid manifest. Returns 2 without populating PC_ERRORS"},
{"lineNum":"  138","line":"\t# when the document uses a construct outside the supported subset."},
{"lineNum":"  139","line":"\tlocal text=\"$1\" parse_status=0","class":"lineCov","hits":"1","order":"703",},
{"lineNum":"  140","line":"\tpc_errors_reset","class":"lineCov","hits":"1","order":"704",},
{"lineNum":"  141","line":"\tPM_SUBSET_DETAIL=\"\"","class":"lineCov","hits":"1","order":"658",},
{"lineNum":"  142","line":"\tpm_parse_manifest \"$text\" || parse_status=$?","class":"lineCov","hits":"1","order":"656",},
{"lineNum":"  143","line":"\t# An out-of-subset refusal propagates so the caller can distinguish it from"},
{"lineNum":"  144","line":"\t# a validation verdict; an M1 failure returns the single-element error list"},
{"lineNum":"  145","line":"\t# already accumulated, because no field check is meaningful without a"},
{"lineNum":"  146","line":"\t# mapping to read fields from."},
{"lineNum":"  147","line":"\tif ((parse_status == 2)); then","class":"lineCov","hits":"1","order":"705",},
{"lineNum":"  148","line":"\t\treturn 2","class":"lineNoCov","hits":"0",},
{"lineNum":"  149","line":"\tfi"},
{"lineNum":"  150","line":"\tif ((parse_status != 0)); then","class":"lineCov","hits":"1","order":"706",},
{"lineNum":"  151","line":"\t\treturn 0","class":"lineCov","hits":"1","order":"668",},
{"lineNum":"  152","line":"\tfi"},
{"lineNum":"  153","line":""},
{"lineNum":"  154","line":"\tpm_validate_identity","class":"lineCov","hits":"1","order":"676",},
{"lineNum":"  155","line":"\tpi_scan_prohibited_keys \"$PM_CONTEXT\" \"$PM_DEEP_PROHIBITED_KEYS\" \"$PM_TOP_LEVEL_PROHIBITED_KEYS\"","class":"lineCov","hits":"1","order":"707",},
{"lineNum":"  156","line":"\t# The manifest carries `kind` on every item, unlike the orchestrator"},
{"lineNum":"  157","line":"\t# checkpoint, so the shared item validator is asked to require it (S1)."},
{"lineNum":"  158","line":"\tpi_validate_items \"items\" \"$PM_CONTEXT\" 1","class":"lineCov","hits":"1","order":"664",},
{"lineNum":"  159","line":"\treturn 0","class":"lineCov","hits":"1","order":"680",},
{"lineNum":"  160","line":"}"},
{"lineNum":"  161","line":""},
{"lineNum":"  162","line":"pm_manifest_mode() {"},
{"lineNum":"  163","line":"\t# Echo the run mode declared by the parsed manifest (invariant M3)."},
{"lineNum":"  164","line":"\t#"},
{"lineNum":"  165","line":"\t# A present but non-string value resolves to the default so this accessor"},
{"lineNum":"  166","line":"\t# always returns a mode; the malformed value is reported separately by"},
{"lineNum":"  167","line":"\t# pm_validate_text."},
{"lineNum":"  168","line":"\tif [[ $(yp_type_of \"mode\") == str ]]; then","class":"lineCov","hits":"1","order":"693",},
{"lineNum":"  169","line":"\t\typ_value_of \"mode\"","class":"lineCov","hits":"1","order":"696",},
{"lineNum":"  170","line":"\telse"},
{"lineNum":"  171","line":"\t\tprintf \'%s\' \"$PM_DEFAULT_MODE\"","class":"lineCov","hits":"1","order":"650",},
{"lineNum":"  172","line":"\tfi"},
{"lineNum":"  173","line":"}"},
{"lineNum":"  174","line":""},
{"lineNum":"  175","line":"pm_manifest_max_concurrency() {"},
{"lineNum":"  176","line":"\t# Echo the fan-out cap declared by the parsed manifest (invariant M4)."},
{"lineNum":"  177","line":"\t#"},
{"lineNum":"  178","line":"\t# A present but non-integer value resolves to the default so this accessor"},
{"lineNum":"  179","line":"\t# always returns an integer; the malformed value is reported separately by"},
{"lineNum":"  180","line":"\t# pm_validate_text. Booleans are classified as `bool` by the scanner and"},
{"lineNum":"  181","line":"\t# therefore never satisfy the integer test."},
{"lineNum":"  182","line":"\tif [[ $(yp_type_of \"max_concurrency\") == int ]]; then","class":"lineCov","hits":"1","order":"682",},
{"lineNum":"  183","line":"\t\typ_value_of \"max_concurrency\"","class":"lineCov","hits":"1","order":"649",},
{"lineNum":"  184","line":"\telse"},
{"lineNum":"  185","line":"\t\tprintf \'%s\' \"$PM_DEFAULT_MAX_CONCURRENCY\"","class":"lineCov","hits":"1","order":"648",},
{"lineNum":"  186","line":"\tfi"},
{"lineNum":"  187","line":"}"},
]};
